 9	    public static void sort(int[] values) {
10	        requireArray(values);
11	        if (values.length < 2) {
12	            return;
13	        }
14	
15	        for (int currentIndex = 1; currentIndex < values.length; currentIndex++) {
16	            insertValue(values, currentIndex);
17	        }
18	    }
19	
20	    public static int[] sortedCopy(int[] values) {
21	        requireArray(values);
22	
23	        int[] copy = Arrays.copyOf(values, values.length);
24	        sort(copy);
25	        return copy;
26	    }
27	
28	    private static void insertValue(int[] values, int currentIndex) {
29	        int valueToInsert = values[currentIndex];
30	        int insertionIndex = findInsertionIndex(values, currentIndex, valueToInsert);
31	
32	        shiftRight(values, insertionIndex, currentIndex);
33	        values[insertionIndex] = valueToInsert;
34	    }
35	
36	    private static int findInsertionIndex(int[] values, int currentIndex, int valueToInsert) {
37	        int scanIndex = currentIndex - 1;
38	
39	        while (scanIndex >= 0 && values[scanIndex] > valueToInsert) {
40	            scanIndex--;
41	        }
42	
43	        return scanIndex + 1;
44	    }
