 9	    public static void sort(int[] values) {
10	        requireArray(values);
11	        sortRange(values, 0, values.length);
12	    }
13	
14	    public static void sortRange(int[] values, int startInclusive, int endExclusive) {
15	        requireArray(values);
16	        requireRange(values.length, startInclusive, endExclusive);
17	        if (endExclusive - startInclusive < 2) {
18	            return;
19	        }
20	
21	        for (int currentIndex = startInclusive + 1; currentIndex < endExclusive; currentIndex++) {
22	            insertValue(values, startInclusive, currentIndex);
23	        }
24	    }
25	
26	    public static int[] sortedCopy(int[] values) {
27	        requireArray(values);
28	
29	        int[] copy = Arrays.copyOf(values, values.length);
30	        sort(copy);
31	        return copy;
32	    }
33	
34	    public static boolean isSorted(int[] values) {
35	        requireArray(values);
36	
37	        for (int index = 1; index < values.length; index++) {
38	            if (values[index - 1] > values[index]) {
39	                return false;
40	            }
41	        }
42	
43	        return true;
44	    }
45	
46	    private static void insertValue(int[] values, int startInclusive, int currentIndex) {
47	        int valueToInsert = values[currentIndex];
48	        int insertionIndex = findInsertionIndex(values, startInclusive, currentIndex, valueToInsert);
49	
50	        shiftRight(values, insertionIndex, currentIndex);
51	        values[insertionIndex] = valueToInsert;
52	    }
53	
54	    private static int findInsertionIndex(
55	            int[] values,
56	            int startInclusive,
57	            int currentIndex,
58	            int valueToInsert) {
59	        int scanIndex = currentIndex - 1;
60	
61	        while (scanIndex >= startInclusive && values[scanIndex] > valueToInsert) {
62	            scanIndex--;
63	        }
64	
65	        return scanIndex + 1;
66	    }
67	
68	    private static void shiftRight(int[] values, int startIndex, int endIndex) {
69	        int length = endIndex - startIndex;
70	        if (length > 0) {
71	            System.arraycopy(values, startIndex, values, startIndex + 1, length);
72	        }
73	    }
74	
75	    private static void requireArray(int[] values) {
76	        if (values == null) {
77	            throw new IllegalArgumentException("values must not be null");
78	        }
79	    }
